using System;
using Microsoft.Xrm.Sdk;

namespace EnterpriseServiceOperationsCrm.Plugins
{
    /// <summary>
    /// Example server-side validation for Service Request records.
    /// Register on Create and Update, PreOperation, Synchronous.
    /// Verify entity logical name and choice values in your own environment.
    /// </summary>
    public sealed class ServiceRequestValidationPlugin : IPlugin
    {
        // Replace with the actual logical name generated by your Dataverse solution.
        private const string EntityName = "escrm_servicerequest";
        private const string SubjectField = "escrm_subject";
        private const string DescriptionField = "escrm_description";

        public void Execute(IServiceProvider serviceProvider)
        {
            var context = (IPluginExecutionContext)serviceProvider.GetService(
                typeof(IPluginExecutionContext));

            if (!string.Equals(context.PrimaryEntityName, EntityName,
                StringComparison.OrdinalIgnoreCase))
            {
                return;
            }

            if (!context.InputParameters.Contains("Target") ||
                !(context.InputParameters["Target"] is Entity target))
            {
                return;
            }

            if (context.MessageName != "Create" && context.MessageName != "Update")
            {
                return;
            }

            // On Update, Target contains only changed columns. If the subject was
            // not included in this update, do not reject the update for that reason.
            if (target.Attributes.Contains(SubjectField))
            {
                var subject = target.GetAttributeValue<string>(SubjectField);
                if (string.IsNullOrWhiteSpace(subject))
                {
                    throw new InvalidPluginExecutionException(
                        "Subject is required for a Service Request.");
                }

                if (subject.Trim().Length > 200)
                {
                    throw new InvalidPluginExecutionException(
                        "Subject cannot exceed 200 characters.");
                }
            }

            if (target.Attributes.Contains(DescriptionField))
            {
                var description = target.GetAttributeValue<string>(DescriptionField);
                if (description != null && description.Length > 4000)
                {
                    throw new InvalidPluginExecutionException(
                        "Description cannot exceed 4,000 characters.");
                }
            }

            // Use tracing for diagnosability; do not log secrets or personal data.
            var tracing = (ITracingService)serviceProvider.GetService(typeof(ITracingService));
            tracing.Trace(
                "ServiceRequestValidationPlugin completed. Message={0}; CorrelationId={1}",
                context.MessageName,
                context.CorrelationId);
        }
    }
}
